"""Generate or verify 20% AI-specific subagent files from the 80% canonical prompts.

Single Source of Truth (SSOT):
  - .agent-team/config.json
  - .agent-team/prompts/<role>.md
  - .agent-team/adapters/<adapter>.json

Usage:
  python scripts/sync_adapters.py          # write generated agent files
  python scripts/sync_adapters.py --check  # fail if any generated file has drifted
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from _report import Violation, print_report

GENERATED_BANNER = (
    "<!-- GENERATED BY scripts/sync_adapters.py — DO NOT EDIT DIRECTLY.\n"
    "     Edit .agent-team/prompts/<role>.md (80%) or .agent-team/adapters/<adapter>.json (20%)\n"
    "     then run: python scripts/sync_adapters.py -->"
)


def load_team_config(root: Path) -> dict:
    return json.loads((root / ".agent-team" / "config.json").read_text(encoding="utf-8"))


def load_adapter(root: Path, adapter_path: str) -> dict:
    return json.loads((root / adapter_path).read_text(encoding="utf-8"))


def render_claude_agent(role_name: str, spec: dict, universal_prompt: str) -> str:
    lines = [
        "---",
        f"name: {role_name}",
        f"description: {spec['description']}",
        f"model: {spec['model']}",
    ]
    if spec.get("effort"):
        lines.append(f"effort: {spec['effort']}")
    if spec.get("isolation"):
        lines.append(f"isolation: {spec['isolation']}")
    lines.append(f"tools: {', '.join(spec['tools'])}")
    lines.append("---")
    lines.append("")
    lines.append(GENERATED_BANNER)
    lines.append("")
    lines.append(universal_prompt.strip())
    if spec.get("addendum"):
        lines.append("")
        lines.append(spec["addendum"].strip())
    return "\n".join(lines) + "\n"


def render_gemini_agent(role_name: str, spec: dict, universal_prompt: str) -> str:
    lines = [
        "---",
        f"name: {role_name}",
        f"description: {spec['description']}",
        f"kind: {spec.get('kind', 'local')}",
        f"model: {spec['model']}",
    ]
    if "temperature" in spec:
        lines.append(f"temperature: {spec['temperature']}")
    if "max_turns" in spec:
        lines.append(f"max_turns: {spec['max_turns']}")
    lines.append("tools:")
    for tool in spec["tools"]:
        lines.append(f"  - {tool}")
    lines.append("---")
    lines.append("")
    lines.append(GENERATED_BANNER)
    lines.append("")
    lines.append(universal_prompt.strip())
    if spec.get("addendum"):
        lines.append("")
        lines.append(spec["addendum"].strip())
    return "\n".join(lines) + "\n"


def expected_outputs(root: Path) -> dict[Path, str]:
    cfg = load_team_config(root)
    outputs: dict[Path, str] = {}
    for adapter_name in cfg.get("enabled_adapters", []):
        adapter_rel = cfg["adapters"][adapter_name]
        adapter = load_adapter(root, adapter_rel)
        agents_dir = root / adapter["agents_dir"]
        fmt = adapter["agent_format"]
        for role_name, spec in adapter["roles"].items():
            prompt_rel = cfg["roles"][role_name]["prompt"]
            universal_prompt = (root / prompt_rel).read_text(encoding="utf-8")
            if fmt == "claude_md":
                content = render_claude_agent(role_name, spec, universal_prompt)
                target = agents_dir / f"{role_name}.md"
            elif fmt == "gemini_md":
                content = render_gemini_agent(role_name, spec, universal_prompt)
                target = agents_dir / f"{role_name}.md"
            else:
                raise ValueError(f"Unsupported agent_format: {fmt}")
            outputs[target] = content
    return outputs


def check_sync(root: Path) -> list[Violation]:
    out: list[Violation] = []
    if not (root / ".agent-team" / "config.json").exists():
        return [
            Violation(
                "TEAM-007",
                ".agent-team/config.json",
                0,
                "Missing .agent-team/config.json; 80/20 adapter sync cannot be verified.",
                "Create .agent-team/config.json declaring enabled_adapters and canonical role prompts.",
            )
        ]
    for path, expected in sorted(expected_outputs(root).items()):
        rel = path.relative_to(root).as_posix()
        if not path.exists():
            out.append(
                Violation(
                    "TEAM-007",
                    rel,
                    0,
                    "Adapter subagent file is missing.",
                    "Run 'python scripts/sync_adapters.py' to generate all enabled adapter files.",
                )
            )
            continue
        actual = path.read_text(encoding="utf-8").replace("\r\n", "\n")
        if actual != expected:
            out.append(
                Violation(
                    "TEAM-007",
                    rel,
                    1,
                    "Adapter subagent file drifted from the 80% canonical prompt or 20% adapter manifest.",
                    "Edit .agent-team/prompts/<role>.md or .agent-team/adapters/<adapter>.json, then run 'python scripts/sync_adapters.py'.",
                )
            )
    return out


def sync_all(root: Path) -> list[Path]:
    written: list[Path] = []
    for path, content in sorted(expected_outputs(root).items()):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
        written.append(path)
    return written


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--root", default=Path(__file__).resolve().parent.parent, type=Path)
    parser.add_argument("--check", action="store_true", help="verify generated files match SSOT without writing")
    args = parser.parse_args()
    root = args.root.resolve()
    if args.check:
        return print_report("Adapter sync", check_sync(root))
    written = sync_all(root)
    for p in written:
        print(f"Synced {p.relative_to(root).as_posix()}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
